<?php
declare(strict_types=1);namespace MiniErp\Repositories;use PDO;final class PlatformAdminRepository{public function __construct(private PDO $pdo){}public function count():int{return(int)$this->pdo->query('SELECT COUNT(*) FROM platform_admin_users')->fetchColumn();}public function findByEmail(string $email):?array{$s=$this->pdo->prepare('SELECT *,locked_until IS NOT NULL AND locked_until>NOW() AS is_locked FROM platform_admin_users WHERE email=? LIMIT 1');$s->execute([strtolower(trim($email))]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}public function findActiveIdentity(int $id):?array{$s=$this->pdo->prepare('SELECT id,name,email,role FROM platform_admin_users WHERE id=? AND active=1 LIMIT 1');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}public function create(string $name,string $email,string $hash,string $role='SUPER_ADMIN'):int{$s=$this->pdo->prepare('INSERT INTO platform_admin_users(name,email,password_hash,role,password_changed_at) VALUES(?,?,?,?,NOW())');$s->execute([trim($name),strtolower(trim($email)),$hash,$role]);$id=(int)$this->pdo->lastInsertId();$this->audit($id,'ADMIN_CREATED','platform_admin_user',(string)$id,null,['source'=>'CLI']);return$id;}public function loginFailed(?int $id,?string $ip):void{if($id)$this->pdo->prepare('UPDATE platform_admin_users SET failed_login_attempts=failed_login_attempts+1,locked_until=IF(failed_login_attempts>=5,DATE_ADD(NOW(),INTERVAL 15 MINUTE),locked_until) WHERE id=?')->execute([$id]);$this->audit($id,'LOGIN_FAILED','platform_admin_user',$id?(string)$id:null,$ip);}public function loginSucceeded(int $id,?string $ip):void{$this->pdo->prepare('UPDATE platform_admin_users SET failed_login_attempts=0,locked_until=NULL,last_login_at=NOW() WHERE id=?')->execute([$id]);$this->audit($id,'LOGIN_SUCCESS','platform_admin_user',(string)$id,$ip);}public function changePassword(int $id,string $hash,string $source):void{$this->pdo->prepare('UPDATE platform_admin_users SET password_hash=?,password_changed_at=NOW(),failed_login_attempts=0,locked_until=NULL WHERE id=?')->execute([$hash,$id]);$this->audit($id,'PASSWORD_CHANGED','platform_admin_user',(string)$id,null,['source'=>$source]);}public function audit(?int $id,string $action,?string $targetType=null,?string $targetId=null,?string $ip=null,array $metadata=[]):void{$s=$this->pdo->prepare('INSERT INTO platform_admin_audit_log(admin_id,action,target_type,target_id,ip_address,metadata_json) VALUES(?,?,?,?,?,?)');$s->execute([$id,$action,$targetType,$targetId,$ip,$metadata?json_encode($metadata,JSON_THROW_ON_ERROR):null]);}}
